import java.util.*;

class Solution {
    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        dfs(root, targetSum, new ArrayList<>(), result);
        return result;
    }

    private void dfs(TreeNode node, int remaining, List<Integer> path, List<List<Integer>> result) {
        if (node == null) {
            return;
        }

        path.add(node.val);
        if (node.left == null && node.right == null && remaining == node.val) {
            result.add(new ArrayList<>(path));
        } else {
            int nextRemaining = remaining - node.val;
            dfs(node.left, nextRemaining, path, result);
            dfs(node.right, nextRemaining, path, result);
        }
        path.remove(path.size() - 1);
    }
}

import java.util.*;

class Solution {
    private static final class Frame {
        final TreeNode node;
        final int remaining;
        final List<Integer> path;

        Frame(TreeNode node, int remaining, List<Integer> path) {
            this.node = node;
            this.remaining = remaining;
            this.path = path;
        }
    }

    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        List<Integer> path = new ArrayList<>();
        path.add(root.val);
        Deque<Frame> stack = new ArrayDeque<>();
        stack.push(new Frame(root, targetSum - root.val, path));
        while (!stack.isEmpty()) {
            Frame frame = stack.pop();
            TreeNode node = frame.node;
            if (node.left == null && node.right == null && frame.remaining == 0) {
                result.add(frame.path);
                continue;
            }
            if (node.right != null) {
                List<Integer> rightPath = new ArrayList<>(frame.path);
                rightPath.add(node.right.val);
                stack.push(new Frame(node.right, frame.remaining - node.right.val, rightPath));
            }
            if (node.left != null) {
                List<Integer> leftPath = new ArrayList<>(frame.path);
                leftPath.add(node.left.val);
                stack.push(new Frame(node.left, frame.remaining - node.left.val, leftPath));
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    private static final class Frame {
        final TreeNode node;
        final int sum;
        final List<Integer> path;

        Frame(TreeNode node, int sum, List<Integer> path) {
            this.node = node;
            this.sum = sum;
            this.path = path;
        }
    }

    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        List<Integer> firstPath = new ArrayList<>();
        firstPath.add(root.val);
        Queue<Frame> queue = new ArrayDeque<>();
        queue.offer(new Frame(root, root.val, firstPath));
        while (!queue.isEmpty()) {
            Frame frame = queue.poll();
            TreeNode node = frame.node;
            if (node.left == null && node.right == null && frame.sum == targetSum) {
                result.add(frame.path);
            }
            if (node.left != null) {
                List<Integer> leftPath = new ArrayList<>(frame.path);
                leftPath.add(node.left.val);
                queue.offer(new Frame(node.left, frame.sum + node.left.val, leftPath));
            }
            if (node.right != null) {
                List<Integer> rightPath = new ArrayList<>(frame.path);
                rightPath.add(node.right.val);
                queue.offer(new Frame(node.right, frame.sum + node.right.val, rightPath));
            }
        }
        return result;
    }
}

import java.util.*;

class Solution {
    public List<List<Integer>> pathSum(TreeNode root, int targetSum) {
        List<List<Integer>> result = new ArrayList<>();
        if (root == null) {
            return result;
        }

        Map<TreeNode, TreeNode> parent = new HashMap<>();
        Map<TreeNode, Integer> sum = new HashMap<>();
        Queue<TreeNode> queue = new ArrayDeque<>();
        queue.offer(root);
        parent.put(root, null);
        sum.put(root, root.val);

        while (!queue.isEmpty()) {
            TreeNode node = queue.poll();
            int currentSum = sum.get(node);
            if (node.left == null && node.right == null && currentSum == targetSum) {
                result.add(reconstruct(node, parent));
            }
            if (node.left != null) {
                parent.put(node.left, node);
                sum.put(node.left, currentSum + node.left.val);
                queue.offer(node.left);
            }
            if (node.right != null) {
                parent.put(node.right, node);
                sum.put(node.right, currentSum + node.right.val);
                queue.offer(node.right);
            }
        }
        return result;
    }

    private List<Integer> reconstruct(TreeNode node, Map<TreeNode, TreeNode> parent) {
        LinkedList<Integer> path = new LinkedList<>();
        while (node != null) {
            path.addFirst(node.val);
            node = parent.get(node);
        }
        return path;
    }
}
